custom_css:
/* ----------
来自@咩野(dc@lambkinling);
有使用KAKAA老师二改盒子中的部分代码、以及NAKARI和墨千尾老师在教程帖分享的代码；
二改需标注，禁二传，倒卖👊🏻👊🏻👊🏻；
 ---------- */

/* 标注信息:🔸→自定义，🐑→错位修改 */

:root {
   /* 边框圆角 */
  --border-radius-small: 3px;
  --border-radius-medium: 5px;
  --头像下方字体颜色: white;
  --字体阴影: var(--SmartThemeShadowColor);
  --毛玻璃效果: 20px;
  /* 🔸↑以上自调整↑🔸 */
  --scroll-width: 4px;
  --混合色: color-mix(in srgb, var(--SmartThemeBotMesBlurTintColor) 50%, var(--SmartThemeUserMesBlurTintColor));
  --渐变色-1: color-mix(in srgb, var(--SmartThemeUserMesBlurTintColor) 98%, transparent);
  --渐变色-2: color-mix(in srgb, var(--SmartThemeBotMesBlurTintColor) 98%, transparent);
  --渐变色-3: color-mix(in srgb, var(--SmartThemeUserMesBlurTintColor) 30%, transparent);
}

/* 🔹视觉小说模式 */
:root {
  --visual-novel-height: 40dvh; /* 🔹高度调整 */
}

body.waifuMode #sheld {
  background: transparent !important;
  margin: 0;
  padding: 0;
  top: var(--visual-novel-height);
  height: calc(100dvh - var(--visual-novel-height));
  -webkit-mask-image: linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 🔹模糊遮罩(iOS端) */
    rgba(0, 0, 0, 0) 100%);
  mask-image: linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 🔹模糊遮罩(0.8和百分比都可以调整) */
    rgba(0, 0, 0, 0) 100%);
}

body.waifuMode #form_sheld {
  position: sticky;
  bottom: 0px; /* 底栏高度 */
}

body.waifuMode #send_form {
  width: 100%; /* 底栏宽度 */
}

/* 滚动条 */
::-webkit-scrollbar {
  display: none;
}

html {
  scrollbar-width: auto;
  scrollbar-color: var(--混合色) #f1f1f1;
}

/* 滑动条 */
input[type="range"] {
  background: transparent !important;
  color: transparent;
  border-radius: var(--border-radius-medium);
  filter: none !important;
  box-shadow:
    inset 1px 1px 2px var(--SmartThemeShadowColor) !important;
}

input[type="range"]::-webkit-slider-thumb {
  clip-path: polygon(50% 100%, 0 45%, 0 15%, 25% 0, 50% 25%, 75% 0, 100% 15%, 100% 45%);
  background: 
      linear-gradient(to right, 
      var(--渐变色-2) 0%, 
      var(--渐变色-1) 100%);
  background-color: #fff;
  border: none;
  transform: scale(1.35);
}

.list-group,
.options-content,
#extensionsMenu,
#options {
  box-shadow: none !important;
  background: transparent !important;
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 全局头像 */
.avatar img,
body.big-avatar .avatar img {
  box-shadow: none;
  border: none;
}

/* ---------- 文本样式 ---------- */
/* 引用文本 */
q {
  color: transparent;
  background: 
    linear-gradient(165deg, 
    var(--渐变色-1) 0%, 
    var(--渐变色-2) 100%);
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: text;
  -moz-background-clip: text;
  background-clip: text;
}
/* 斜体文本 */
em {
  font-style: italic;
  background-color: var(--渐变色-3); 
  padding: 0.1em 0.3em;
  border-radius: 3px;
}
/* 删除文本 */
del, s {
  color: red;
}

/* ----------- 聊天区域 ---------- */
#sheld{
  top: var(--topBarBlockSize);
  height: calc(100dvh - var(--topBarBlockSize) - 1px);
  min-height: calc(100dvh - var(--topBarBlockSize)); /* ⚠️用视觉小说模式就把一行删掉 */
}

#form_sheld {
  margin: 0 auto;
  position: sticky;
  bottom: 2px; /* 底栏高度 */
}

 /* 思维链 */
.mes_reasoning_header {
  position: relative;
  border-radius: 30px;
  background: transparent;
  border: none;
  box-shadow: 
    -1px -1px 2px rgba(255, 255, 255, 0.1),
    1px 1px 2px var(--SmartThemeShadowColor);
}

.mes_reasoning_header_title::before {
  position: relative;
  content: "▷ ︎ıllıııllıl ♪"; /* 🔸思维链文字 */
  font-size: var(--mainFontSize);
  z-index: 2;
}

.mes_reasoning_header_title {
    font-size: 0;
}

.mes_reasoning_header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 0;
    height: 100%;
    background-image: 
      linear-gradient(to right, 
      var(--渐变色-2) 0%, 
      var(--渐变色-1) 100%);
    transition: width 0.5s ease;
    z-index: 1;
    border-radius: 30px;
}

.mes_reasoning_header:hover::before {
    width: 100%;
}

/* 聊天框 */
#chat {
  align-items: center;
  background: transparent;
  border: none;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
}
@supports(-webkit-touch-callout: none){
  #chat {
    padding-right: var(--scroll-width);
  }
}

/* 气泡框 */
.mes {
  flex-direction: column;
  align-items: center;
  width: 100%;
  padding: 0;
  border-radius: var(--border-radius-small);
  background: transparent;
}

/* 最新消息与底栏距离 */
.last_mes {
  margin-bottom: 20px !important;
}

/* 消息块 */
body .mes_block {
  display: flex;
  flex-direction: column;
  width: 95%;
  padding: 15px;
  border-radius: var(--border-radius-medium);
  border: none;
  background: var(--SmartThemeChatTintColor);
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
  box-shadow: 0 0 3px var(--SmartThemeShadowColor); /* 气泡框阴影 */
}

/* 避免遮挡箭头 */
 .last_mes .mes_block {
  padding-bottom: 60px !important;
}

/* 控制消息间距 */
div[is_user="true"] .mes_block {
  margin-top: 20px;
  margin-bottom: 2px;
}

div[is_user="false"] .mes_block {
  margin-top: 2px;
}

/* 文本 */
.mes_text {
  padding: 0;
  text-align: justify;
}

/* 头像区域 */
.mesAvatarWrapper {
  position: relative;
  align-items: center;
  justify-content: center;
  width: 95%;
  aspect-ratio: 24 / 7;
  max-width: 332px; /* 🐑 */
  padding: 0;
  background: transparent;
  margin: 0 auto;
}

/* 最后一条消息 */
.last_mes .mesAvatarWrapper {
  padding: 0 !important;
}

/* 头像容器 */
.mesAvatarWrapper .avatar {
  position: absolute;
  justify-content: center;
  width: auto;
  pointer-events: none;
}

/* 用户头像区域 */
div[is_user="true"] .mesAvatarWrapper {
  display: flex;
  flex-direction: row;
  justify-content: flex-end;
  order: 1;
}

/* 🐑用户头像位置调整(left&top) */
div[is_user="true"] .mesAvatarWrapper .avatar {
  left: 61.5%; 
  top: 74%;
  margin: 0;
  transform: translateX(-50%) scale(1.5);  /* 头像大小scale */
}

/* 右耳耳机 */
div[is_user="true"] .mesAvatarWrapper .avatar::after {
  content: "";
  display: block;
  position: absolute;
  width: 40px; /* 调整大小 */
  height: 40px;
  background-image: url("https://i.postimg.cc/5tfcRyq6/21-20250809162149.png");
  filter: brightness(1); /* 🔸白耳机改1,黑耳机改0 */
  background-size: cover;
  background-repeat: no-repeat;
  bottom: 5px; /* 🐑 */
  right: -11px;
  transform: translateX(-50%) scale(1.8);
  z-index: -1;
}

/* AI 头像区域 */
div[is_user="false"] .mesAvatarWrapper {
  display: grid;
  grid-template-rows: auto auto;
  justify-items: center;
  align-items: start;
}

/* 🐑AI 头像位置调整 */
div[is_user="false"] .mesAvatarWrapper .avatar {
  position: relative;
  grid-row: 1;
  grid-column: 2;
  transform: translateX(50%) scale(1.5); 
  left: -57.5%; /* 🐑 */
  top: -50%;
}

div[is_user="false"] .mesAvatarWrapper {
  display: grid;
  place-items: center;
  position: relative;
}

/* 左耳耳机 */
div[is_user="false"] .mesAvatarWrapper .avatar::after {
  content: "";
  display: block;
  position: absolute;
  width: 40px;
  height: 40px;
  background: 
    url("https://i.postimg.cc/wBFK8z0F/21-20250809162207.png");
  filter: brightness(1); /* 🔸黑耳机调成0，白1 */
  background-size: cover;
  background-repeat: no-repeat;
  bottom: 4.3px; /* 🐑调整位置 */
  right: -19px;
  transform: translateX(-50%) scale(1.8);
  z-index: -1; 
}

/* 🔸🐑通用头像框 */
.mesAvatarWrapper .avatar::before {
  content: "";
  display: block;
  position: absolute;
  width: 32px; /* 调整大小 */
  height: 32px;
  background-image: url("https://i.postimg.cc/66S5b6nf/1754884779760.gif");
  background-size: cover;
  background-repeat: no-repeat;
  bottom: 18%; /* 🐑 */
  right: -15%;
  transform: translateX(-50%) scale(1.8);
  z-index: 2;
}

/* 🔸自定义文字，\A是换行符 */
div[is_user="false"] .mesAvatarWrapper::before {
  content: "@自定义 & @自定义\A✩ ⋆ ┄ ⋆ 我和你，最天生一对 ⋆ ┄ ⋆ ✩ ";
  white-space: pre;
  position: absolute;
  z-index: 1;
  margin-top: 10px;
  font-size: 0.8em;
  text-align: center;
}

/* 楼层、计时器、tokens */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: flex !important;
  position: relative;
  align-items: center;
  color: var(--SmartThemeQuoteColor);
  opacity: 1 !important;
}

.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty{
  display: none;
}

/* 用户元信息 */
.mes[is_user="true"] .mesAvatarWrapper .mes_timer {
  display: none !important;
}

/* 五角星 */
div[is_user="true"] .mesAvatarWrapper .mesIDDisplay::before {
  content: "";
  display: inline-block;
  width: 1.4em;
  height: 1.4em;
  margin-right:  1px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="gold" d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>');
  background-size: contain;
}

/* 爱心 */
div[is_user="true"] .mesAvatarWrapper .tokenCounterDisplay::before {
  content: "";
  display: inline-block;
  width: 1.3em;
  height: 1.3em;
  margin: 0 1px 0 6px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 24 24"><path fill="%23ff0000" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>');
  background-size: contain;
}

div[is_user="true"] .mesAvatarWrapper .mesIDDisplay:hover::before,
div[is_user="true"] .mesAvatarWrapper .tokenCounterDisplay:hover::before {
  filter: grayscale(100%) brightness(0.7);
}

/* 头像下方字体 */
div[is_user="true"] .mesAvatarWrapper .tokenCounterDisplay,
div[is_user="true"] .mesAvatarWrapper .mesIDDisplay,
div[is_user="false"] .mesAvatarWrapper::before,
div[is_user="false"] .mesAvatarWrapper .mesIDDisplay::before,
div[is_user="false"] .mesAvatarWrapper .mes_timer::before,
div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay::before,
div[is_user="false"] .mesAvatarWrapper .mesIDDisplay::after,
div[is_user="false"] .mesAvatarWrapper .mes_timer::after,
div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay::after {
  color: var(--头像下方字体颜色);
  text-shadow: 0 0 3px var(--字体阴影) !important; /* 字体外发光 */
}

/* 🔸AI元信息(文字自定义) */
div[is_user="false"] .mesAvatarWrapper .mesIDDisplay::before {
  content: "共同喜欢 ";
}

div[is_user="false"] .mesAvatarWrapper .mesIDDisplay::after {
  content: " 首歌";
}

div[is_user="false"] .mesAvatarWrapper .mes_timer::before {
  content: "距离 ";
}

div[is_user="false"] .mesAvatarWrapper .mes_timer::after {
  content: " 公里，";
}

div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay::before {
  content: "一起听了 ";
}

div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay::after {
  content: " 小时，";
}

/* 其他子元素横向排列 */
div[is_user="false"] .mesAvatarWrapper > :not(.avatar) {
  grid-row: 2; 
  display: flex;
  flex-wrap: wrap; 
  row-gap: 2px; 
  column-gap: 2px; /* 元信息间距 */
  justify-content: center;
}

/* 调整子元素排序 */
div[is_user="false"] .mesAvatarWrapper > .mesIDDisplay { order: 3; }
div[is_user="false"] .mesAvatarWrapper > .mes_timer { order: 1; }
div[is_user="false"] .mesAvatarWrapper > .tokenCounterDisplay { order: 2; }

/* 为每个子项添加最小宽度 */
div[is_user="false"] .mesAvatarWrapper .mesIDDisplay,
div[is_user="false"] .mesAvatarWrapper .mes_timer,
div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay {
  min-width: max-content;
}

/* 欢迎页 */
.welcomePanel {
  margin-bottom: 50px !important;
}

/* 小铅笔 */
.mes_button,
.mes_edit_buttons,
.mes .extraMesButtons {
  filter: none !important;
  box-shadow: none !important;
  font-size: 0.85em;
}

.mes_edit_buttons .mes_edit_delete{
  background-color: red;
}

/* ai消息左右箭头 */
.swipe_left,
.swipe_right {
  opacity: 0.6 !important; /* 箭头透明度 */
  color: var(--混合色);
}

.swipeRightBlock{
  padding-right: 20px; /* 右箭头左右位置 */
}

/* 提示词拆分 */
.popup-content:has(#showRawPrompt) {
  max-height: 80vh;
  overflow-y: auto;
  padding-right: 15px;
}

/* 名字底部渐变下划线 */
.ch_name.flex-container.justifySpaceBetween {
  position: relative;
  padding-bottom: 2px;
  margin-bottom: 6px;
}

.ch_name.flex-container.justifySpaceBetween::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background: linear-gradient(
    to right,
    transparent,
    var(--SmartThemeShadowColor),
    transparent
  );
  z-index: 1;
  opacity: 0.15;
}

/* ----------- 顶栏 & 底栏 ---------- */
/* 底栏 */
#send_form,
body.no-blur #send_form {
  width: 97%; /* 宽度 */
  border-radius: var(--border-radius-medium);
  border: 3px solid var(--SmartThemeBorderColor) !important;
  outline: 1px solid var(--混合色) !important;
  box-shadow: none;
  padding: 3px !important;
  background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 1%, transparent) !important;
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

#send_form:hover, body.no-blur #send_form:hover {
  transform: translateY(-5px);
}

/* 顶栏 */
#top-bar,
body.no-blur #top-bar {
  width: 99%;
  top: 1px;
  border-radius: var(--border-radius-medium);
  border: 2px solid var(--SmartThemeBorderColor);
  outline: 1px solid var(--混合色) !important;
  box-shadow: none;
  background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 75%, transparent) !important;
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 顶栏 & 底栏图标 */
.drawer-icon,
#send_form .fa-solid,
#quick-reply-rocket-button {
  display: flex;
  overflow: visible;
  transform-origin: center;
  justify-content: center;
  opacity: 0.7 !important;
  font-size: calc(var(--mainFontSize) * 1.2);
  text-shadow: none !important;
  background: 
    linear-gradient(125deg, 
    var(--渐变色-2) 0%, 
    var(--渐变色-1) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  transition: all 0.5s ease;
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
}

.drawer-icon:hover, .drawer-icon.openIcon {
  overflow: visible;
  position: relative;
  font-size: calc(var(--mainFontSize) * 1.6);
  background: 
    linear-gradient(165deg, 
    var(--渐变色-1) 0%, 
    var(--渐变色-2) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

#send_form .fa-solid,
#quick-reply-rocket-button {
  font-size: calc(var(--mainFontSize) * 1.5);
  text-shadow: none !important;
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
}

#send_form .fa-solid:hover,
#quick-reply-rocket-button:hover {
  opacity: 1;
  background: 
    linear-gradient(180deg, 
    var(--渐变色-2) 0%, 
    var(--渐变色-1));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* 输入框自定义文案 by墨千尾 */
#nonQRFormItems {
    position: relative;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "· 𓈒𓏸˚₊ 思念送達中◌·˚⊹"; /* 🔸自定义文案 */
    color: transparent;
  background: linear-gradient(165deg, 
    var(--渐变色-2) 0%, 
    var(--渐变色-1) 100%);
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: text;
  -moz-background-clip: text;
  background-clip: text;
  color: transparent; 
    position: absolute;
    top: 44%;
    left: 33%; /* 🐑错位调整 */
    transform: translateY(-50%);
    font-size: 0.5em;
    pointer-events: none; 
    z-index: 10;
    white-space: nowrap; 
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}

/* ----------- 抽屉页 ---------- */
body .drawer-content {
  border: none !important;
  border-radius: 0 0 var(--border-radius-medium) var(--border-radius-medium);
  background: var(--SmartThemeBlurTintColor);
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  box-shadow:  0 0 3px var(--SmartThemeShadowColor);
  border-radius: var(--border-radius-small);
  border: none;
  outline: none;
  background: var(--SmartThemeBlurTintColor);
  margin-bottom: 6px;
  transition: background 0.2s ease-in-out;
}

/* 正则防误触&全显 */
#saved_regex_scripts, 
#saved_scoped_scripts {
  padding-right: 45px; 
}

.regex_script_name.flexGrow.overflow-hidden {
  overflow: visible;
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

/* 拓展页输入助手 */
.integrated-button-row {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border-radius: var(--border-radius-small) !important;
  padding: 1px 7px!important;
}
.integrated-button-row .button-preview,
.integrated-button-row .shortcut-input,
.integrated-button-row .shortcut-clear-btn,
.integrated-button-row .custom-edit-btn,
.integrated-button-row .custom-edit-btn {
  transform: scale(0.8);
}

/* 下拉框 */
select {
  border: none !important;
  background-color: var(--SmartThemeBlurTintColor);
  box-shadow: 0 0 3px var(--SmartThemeShadowColor);
  margin-bottom: 3px !important;
}

/* 勾选框 */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  border: none;
  filter: none;
  box-shadow: none;
  background-color: rgba(197, 197, 197, 0.5);
  clip-path: polygon(50% 100%, 0 45%, 0 15%, 25% 0, 50% 25%, 75% 0, 100% 15%, 100% 45%);
  transition: background-color 0.2s ease-in-out;
}

input[type="checkbox"]:checked {
  background-image: 
    linear-gradient(135deg, 
      var(--渐变色-1) 0%, 
      var(--渐变色-2) 100%);
}

input[type="checkbox"]::before {
  content: none !important;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

/* 标题栏 */
.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder),
#user-settings-block h4, 
.standoutHeader {
  background: var(--SmartThemeBlurTintColor);
  box-shadow: 0 0 3px var(--SmartThemeShadowColor);
  border-radius: var(--border-radius-medium);
  outline: none;
  border: none;
  margin-bottom: 5px;
  padding-left: 7px;
}

/* 缩小锁定图标 & 箭头 */
#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div,
.inline-drawer-icon {
  font-size: var(--mainFontSize);
}

.inline-drawer-icon {
  padding-right: 3px;
  filter: none;
}

/* 按钮 */
.menu_button:not(.mes_edit_buttons *) {
  background: var(--SmartThemeBlurTintColor);
  border-radius: var(--border-radius-medium);
  border: none !important;
  filter: none;
  box-shadow: 0 0 3px var(--SmartThemeShadowColor);
}

/* 提示词管理器 */
#completion_prompt_manager {
  width: 100%;
}
#completion_prompt_manager_list .completion_prompt_manager_list_separator {
  display: none !important;
}

/* “提示词&总词符数” */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  filter: none;
}
#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeQuoteColor) !important;
  padding: 0;
}
.completion_prompt_manager_footer {
  padding: 0 !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: var(--border-radius-small);
  border: 1.2px solid;
  filter: none;
}

/* 悬停&激活 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:focus {
  box-shadow: 2px 2px 4px var(--SmartThemeShadowColor);
  border-radius: var(--border-radius-small);
}

/* 去除阴影 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
  filter: none !important;
}

/* 🔺未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color:  color-mix(in srgb, var(--SmartThemeUnderlineColor) 50%, transparent);
}

/* 启用状态的开关按钮 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
  color: var(--SmartThemeUnderlineColor) !important;
  filter: none;
  box-shadow: none;
}

/* 用户管理器 */
.avatar-container.selected{
  background: var(--渐变色-3);
  border: 2px groove var(--混合色);
}

#movingUIPresets{
  margin-bottom: 0 !important;
}

/* 星标角色卡 */
.character_select.is_fav .avatar {
  outline: 2px solid var(--混合色);
}
.character_select.is_fav .ch_name {
    color: transparent;
  background: 
    linear-gradient(165deg, 
    var(--渐变色-1) 0%, 
    var(--渐变色-2) 100%);
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: text;
  -moz-background-clip: text;
  background-clip: text;
}
.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}
.tag.actionable {
  font-size: calc(var(--mainFontSize) * 1);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区滚动条 */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + var(--scroll-width) + 10px);
  max-height: calc(var(--avatar-base-height)* 2);
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--混合色);
}
.avatars_inline {
  gap: 5px;
  flex-wrap: nowrap;
  overflow: visible;
}

/* 世界书容器 */
#WorldInfo {
  margin-top: 0;
}
/* 世界书弹出窗口（iOS特定样式)  */
@supports (-webkit-touch-callout: none) {
  #world_popup {
    margin-top: 0;
    width: 100%;
  }
}

/* 世界书条目卡片 */
.wi-card-entry {
  background: var(--SmartThemeBlurTintColor) !important;
  margin-bottom: 5px;
  padding-left: 0;
  border-radius: var(--border-radius-medium);
}

/* 移动端响应式样式 */
@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header {
    background: transparent !important;
    border-radius: var(--border-radius-medium) var(--border-radius-medium) var(--border-radius-medium) 0;
    box-shadow: none;
    border: none;
    outline: none;
  }
}

/* 世界书单击展开 */
.inline-drawer-content {
    background-color: transparent !important;
}

.inline-drawer-toggle:hover, 
.inline-drawer-toggle:focus {
    filter: none !important;
}

/* 输入框 */
input, textarea {
  -webkit-appearance: none; /* 禁用 iOS 默认样式 */
  appearance: none;
}

input[type="switch"],
input[type="text"],
input:not([type]),
textarea:not([type="search"]):not(.send_textarea) {
  background: var(--SmartThemeBlurTintColor);
  border: none;
  border-radius: var(--border-radius-small);
  box-shadow: 0 0 3px var(--SmartThemeShadowColor);
}

input[type="text"]:focus,
input[type="number"]:focus,
input[type="switch"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):not(.send_textarea):focus{
  border: none;
  border-radius: var(--border-radius-small);
}

input[type="number"] {
  background: var(--SmartThemeBlurTintColor);
  box-shadow: 0 0 2px var(--SmartThemeShadowColor);
  border: none;
}

/* 特殊输入框 */
.text_pole:not(.objective-task) {
  background: var(--SmartThemeBlurTintColor);
  border-radius: var(--border-radius-medium);
  border: none;
  box-shadow: 0 0 3px var(--SmartThemeShadowColor);
}

/* 通知提示框 */
div.toast.toast-error {
  border-radius: var(--border-radius-medium) !important;
  border: 1.2px solid gray !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important;
}

div.toast.toast-success {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border-radius: var(--border-radius-medium) !important;
  color: var(--SmartThemeBodyColor) !important;
  border: 2px solid var(--混合色);
  box-shadow: 0 0 3px var(--SmartThemeShadowColor) !important;
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
}

/* 代码样式 */
code {
  background-color: var(--SmartThemeBlurTintColor);
  color: var(--SmartThemeUnderlineColor);
  border-left: 2px solid var(--渐变色-1);
  border-bottom: 1px solid var(--渐变色-1);
  border-right: 2px solid var(--渐变色-2);
  border-top: 1px solid var(--渐变色-2);
  padding: 0 3px;
  letter-spacing: 0.5px;
}

/* pre元素 */
pre {
  background-color: var(--SmartThemeBlurTintColor);
  border-left: 5px solid var(--渐变色-1);
  border-right: 5px solid var(--渐变色-2);
  padding: 15px;
  position: relative;
  overflow: auto;
}

pre::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 10px;
  height: 1px;
  background: repeating-linear-gradient(
    to right,
    var(--渐变色-1),
    var(--渐变色-1) 10px,
    transparent 10px,
    transparent 20px
  );
}

pre::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 10px;
  height: 1px;
  background: repeating-linear-gradient(
    to right,
    var(--渐变色-2),
    var(--渐变色-2) 10px,
    transparent 10px,
    transparent 20px
  );
}

/* 💓跳动的心 */
div[is_user="true"].mes::after {
  content: "";
  position: absolute;
  bottom: 10%;  /* bottom&left位置调整*/
  left: 43.5%;
  width: 40px;  /* 大小调整 */
  height: 40px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 24 24"><path fill="%23ff0000" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>');
  background-size: contain;
  filter: drop-shadow(0 0 2px #ff0000);
  animation: twinkle 3s ease infinite;
}

@keyframes twinkle {
  0%, 100% { transform: scale(1.05); opacity: 0.6; }
  25% { transform: scale(1.15); opacity: 0.9; }
  50% { transform: scale(1); opacity: 0.7; }
  75% { transform: scale(1.15); opacity: 0.8; }
}

/* top-bar插件 */
#extensionTopBar {
    background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 50%, transparent) !important;
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
    border-radius: 0 0 var(--border-radius-medium) var(--border-radius-medium) !important;
}

body .popup {
  background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 50%, transparent) !important;
  backdrop-filter: blur(var(--毛玻璃效果)) !important;
  -webkit-backdrop-filter: blur(var(--毛玻璃效果))  !important;
